import os from 'node:os';
const PROBE_URLS = [
    'https://captive.apple.com/hotspot-detect.html',
    'https://cloudflare.com/cdn-cgi/trace',
];
const DEFAULT_TIMEOUT_MS = 5_000;
const hasExternalNetworkInterface = () => {
    const interfaces = os.networkInterfaces();
    return Object.values(interfaces).some((entries) => entries?.some((entry) => entry && !entry.internal));
};
export const isOnline = async (timeoutMs = DEFAULT_TIMEOUT_MS) => {
    if (!hasExternalNetworkInterface()) {
        return false;
    }
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), timeoutMs);
    try {
        await Promise.any(PROBE_URLS.map(async (url) => {
            const response = await fetch(url, { signal: controller.signal });
            if (!response.ok) {
                throw new Error(`connectivity check failed with status ${response.status}`);
            }
            try {
                await response.body?.cancel();
            }
            catch { }
            return true;
        }));
        return true;
    }
    catch {
        return false;
    }
    finally {
        clearTimeout(timeout);
        controller.abort();
    }
};
